// Application-owned local handler for Prompt 94.
// s is the lesson state; p contains validated classroom controls.
switch (action.op) {
    case 'skill.bundle':
        s.files['/skill/SKILL.md'] = '---\nname: inventory-report\ndescription: Produce inventory reports with exact source citations.\n---\n# Inventory report\nRead references/schema.json when needed. Recompute every total.';
        s.files['/skill/references/schema.json'] = '{"required":["total","sources"]}';
        accept({ entrypoint: '/skill/SKILL.md', files: Object.keys(s.files).filter(path => path.startsWith('/skill/')) });
        break;
}
